import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Payment create hides fully paid invoices — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payment create hides fully paid invoices — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/payment-allocatable-invoice-picker-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payment create hides fully paid invoices — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/payment-allocatable-invoice-picker-production-readiness"}]]},"headers":[],"relativePath":"deployment/payment-allocatable-invoice-picker-production-readiness.md","filePath":"deployment/payment-allocatable-invoice-picker-production-readiness.md","lastUpdated":1792280519000}'),i={name:"deployment/payment-allocatable-invoice-picker-production-readiness.md"};function n(r,e,s,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="payment-create-hides-fully-paid-invoices-—-production-readiness-audit" tabindex="-1">Payment create hides fully paid invoices — Production Readiness Audit <a class="header-anchor" href="#payment-create-hides-fully-paid-invoices-—-production-readiness-audit" aria-label="Permalink to &quot;Payment create hides fully paid invoices — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-18</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — feature Pest green; headed payments Playwright <strong>10/10</strong></td></tr><tr><td><strong>Scope</strong></td><td>Payment create allocation picker omits fully paid (and cancelled) invoices; edit keeps already-allocated invoices</td></tr><tr><td><strong>Catalog</strong></td><td>No bump (picker/API query filter only)</td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/payments">Payments user guide</a> · <a href="/developer-guide/payments">Payments developer guide</a> · <a href="/api/tenant-v1-invoices">Invoices API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>When recording a new customer payment, the invoice allocation picker must only offer invoices that can still accept money. Fully paid invoices (<code>status=paid</code> or <code>balance_due = 0</code>) and cancelled invoices are excluded. Draft and unpaid invoices with a remaining balance remain selectable. Editing a <strong>draft</strong> payment still shows invoices already allocated on that payment so existing rows do not disappear from the select.</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> Deploy Backend + Frontend together. No migrate. No new permission.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong></td></tr><tr><td><code>GET /invoices?allocatable=1</code> returns only <code>balance_due &gt; 0</code> and excludes <code>paid</code> / <code>cancelled</code></td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Create payment SPA requests <code>allocatable=1</code></td><td><strong>Pass</strong> (code review)</td></tr><tr><td>Client filter hides paid/cancelled and keeps <code>balance_due &gt; 0</code></td><td><strong>Pass</strong> (Vitest)</td></tr><tr><td>Edit keeps already-allocated invoice ids even when paid</td><td><strong>Pass</strong> (Vitest)</td></tr><tr><td>Create form still validates empty amount</td><td><strong>Pass</strong> (headed Playwright)</td></tr><tr><td>Paid invoice number absent from picker; open invoice present</td><td><strong>Pass</strong> (headed Playwright)</td></tr><tr><td>Existing payments workflow (allocate, post, refund validation, void)</td><td><strong>Pass</strong> (headed Playwright suite)</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>Allocatable list still requires <code>invoices.view</code> / <code>viewAny</code></td><td>Pass</td></tr><tr><td>Assignee scope on invoice list unchanged</td><td>Pass</td></tr><tr><td>Post still rejects paid/cancelled allocations server-side</td><td>Pass (existing <code>CustomerPaymentService::post</code>)</td></tr><tr><td>No new endpoints or permissions</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Medium</td><td>Create payment allocation picker listed fully paid invoices</td><td><strong>Fixed</strong> — API <code>allocatable=1</code> + SPA filter</td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>Edit mode loads unfiltered <code>per_page=100</code> and keeps allocated ids client-side</td><td><strong>Accepted</strong> — draft edits are rare; post still rejects invalid allocations</td></tr><tr><td><strong>I2</strong></td><td>Info</td><td>Local headed run may need <code>CI=1</code> so Playwright starts Vite when port 5173 is down</td><td><strong>Accepted</strong> — operator note only</td></tr></tbody></table><hr><h2 id="headed-browser-coverage" tabindex="-1">Headed browser coverage <a class="header-anchor" href="#headed-browser-coverage" aria-label="Permalink to &quot;Headed browser coverage&quot;">​</a></h2><p><code>CI=1 npm run test:e2e:payments:headed -- --workers=1</code> on 2026-10-18. Result: <strong>10 passed</strong>.</p><p>Authz and Stripe specs each use one demo login (shared session within the file). The payments workflow uses one demo login for the serial path:</p><ol><li>Create form: submit without amount → <strong>Amount is required</strong> (field error under <code>#main-content</code>)</li><li>Allocation picker: fully paid invoice number → no options / empty; open unpaid invoice still listed</li><li>Create payment, allocate to open invoice, post</li><li>Refund dialog validation (empty / over-balance), receipt PDF + email, void</li><li>Stripe dialog enable/save/live-fail/disconnect + portal online payment flag</li><li>Staff without <code>payments.send</code>: download receipt allowed, email hidden / API forbidden</li></ol><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><ol><li>Deploy Backend (no migrate).</li><li>Deploy Frontend SPA and hard-refresh.</li><li>Smoke: open <strong>Payments → New</strong>, allocate — a paid invoice number must not appear; an unpaid invoice with balance must appear.</li></ol>',21)])])}const u=t(i,[["render",n]]);export{h as __pageData,u as default};
